"""Safe media storage. File names are generated by us (never from user input) and re-validated on every access."""
from __future__ import annotations

import hashlib
import re
import struct
import uuid
from pathlib import Path

FILE_RE = re.compile(r"^[a-f0-9]{32}\.(png|jpg|webp)$")
EXT = {"image/png": "png", "image/jpeg": "jpg", "image/webp": "webp"}
MIME = {v: k for k, v in EXT.items()}


def sniff(data: bytes) -> str | None:
    """Real file type from the first bytes (the declared Content-Type is never trusted)."""
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    return None


def dimensions(data: bytes) -> tuple[int | None, int | None]:
    try:
        if data[:8] == b"\x89PNG\r\n\x1a\n":
            w, h = struct.unpack(">II", data[16:24])
            return w, h
        if data[:3] == b"\xff\xd8\xff":
            i = 2
            while i + 9 < len(data):
                if data[i] != 0xFF:
                    i += 1
                    continue
                marker = data[i + 1]
                if marker in (0xD8, 0x01) or 0xD0 <= marker <= 0xD7:
                    i += 2
                    continue
                length = struct.unpack(">H", data[i + 2:i + 4])[0]
                if 0xC0 <= marker <= 0xCF and marker not in (0xC4, 0xC8, 0xCC):
                    h, w = struct.unpack(">HH", data[i + 5:i + 9])
                    return w, h
                i += 2 + length
        if data[:4] == b"RIFF" and data[8:12] == b"WEBP" and data[12:16] == b"VP8X":
            w = 1 + int.from_bytes(data[24:27], "little")
            h = 1 + int.from_bytes(data[27:30], "little")
            return w, h
    except (struct.error, IndexError):
        pass
    return None, None


class MediaStore:
    def __init__(self, root: Path):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    def save(self, data: bytes, mime: str | None = None) -> dict:
        real = sniff(data)
        if real is None:
            raise ValueError("not a PNG, JPEG or WebP image")
        name = f"{uuid.uuid4().hex}.{EXT[real]}"
        tmp = self.root / f".{name}.part"
        tmp.write_bytes(data)
        tmp.replace(self.root / name)
        w, h = dimensions(data)
        return {"file_name": name, "mime": real, "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest(),
                "width": w, "height": h}

    def path(self, name: str) -> Path | None:
        if not FILE_RE.match(name or ""):
            return None
        p = self.root / name
        return p if p.is_file() else None

    def read(self, name: str) -> tuple[str, bytes] | None:
        p = self.path(name)
        if not p:
            return None
        return MIME[p.suffix[1:]], p.read_bytes()

    def delete(self, name: str | None) -> None:
        if name and FILE_RE.match(name):
            try:
                (self.root / name).unlink(missing_ok=True)
            except OSError:
                pass
